// The four attack cards on /attack. Payloads are the requests in demo/attack-cards.md (generated by seed.py); keep them
// in step when the seed changes. "What we'll check" names the checks, never the outcome: the reveal is on the board.

import type { AttackCard } from "@/lib/types";

export interface AttackPayloadDraft {
  thread_id: string;
  from_addr: string;
  reply_to: string;
  subject: string;
  body: string;
}

export interface CardDef {
  id: AttackCard;
  kicker: string;
  title: string;
  description: string;
  checks: string[];
  /** The vendor whose thread the email lands in, for the "Sent into" line. */
  vendor: string;
  payload: AttackPayloadDraft;
  /** AI hijack sends a PDF with the email. */
  takesPdf: boolean;
}

